import random
import math

def isPrime(n, k):
	nn = n - 1
	s = 1
	while nn % 2 ** s == 0:
		s += 1
	s -= 1
	d = int(nn // 2 ** s)
	for i in range(k):
		a = random.randint(2, n - 1)
		x = pow(a, d, n)
		if x == 1 or x == n - 1:
			continue
		flag = True
		for r in range(1, s):
			x = pow(x, 2, n)
			if x == 1:
				return False
			if x == n - 1:
				flag = False
				break
		if not flag:
			continue
		return False
	return True
